// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Call NETM() to set owner and give them totalDistributed tokens
        c.NETM();
        // Step 2: Burn exactly totalDistributed = 250000000e18 tokens from owner
        c.burn(250000000e18);
        // In reference, totalDistributed becomes 0, so totalDistributed < totalSupply, so distributionFinished stays false.
        // But we need to check the difference: after burn, distributionFinished should be false in both?
        // Actually the difference is: reference totalDistributed decreases, bug totalDistributed unchanged.
        // In reference, totalDistributed = 0, totalSupply = 250000000e18, so distributionFinished = false.
        // In bug, totalDistributed = 250000000e18, totalSupply = 250000000e18, so distributionFinished = false as well.
        // We need a scenario where totalDistributed >= totalSupply triggers distributionFinished = true.
        // Let's instead call getTokens() after distributionFinished is false, but in reference totalDistributed is lower, so value < totalRemaining.
        // Actually simpler: after NETM(), totalDistributed = 250000000e18, totalRemaining = 250000000e18.
        // In reference: burn reduces totalDistributed to 0, totalSupply to 250000000e18. So totalDistributed < totalSupply, distributionFinished false.
        // In bug: totalDistributed stays 250000000e18, totalSupply = 250000000e18, so totalDistributed >= totalSupply, distributionFinished = true.
        // So we can check distributionFinished.
        assertTrue(c.distributionFinished() == true, "Bug should have distributionFinished true");
    }
}

