pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Let owner call NETM() to assign totalDistributed to owner's balance
        address owner = address(this);
        c.NETM();
        // Step 2: Owner burns 125000000e18 tokens
        c.burn(125000000e18);
        // Step 3: Now a random user calls getTokens() (payable, but value is 2500e18 initially, and they are not blacklisted)
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getTokens();
        // After getTokens, in reference totalDistributed=125000000e18, totalRemaining=375000000e18, value=min(2500e18,375000000e18)=375000000e18
        // So user gets 375000000e18 tokens, balance = 375000000e18
        // In bug, totalDistributed unchanged at 250000000e18, totalRemaining=250000000e18, value=min(2500e18,250000000e18)=250000000e18
        // So user gets 250000000e18 tokens, balance = 250000000e18
        uint256 userBalance = c.balanceOf(user);
        // Reference gives 375000000e18, bug gives 250000000e18. Thus true: userBalance == 375000000e18
        assertTrue(userBalance == 375000000e18, "Bug should have balance 375000000e18");
    }
}

