        // Owner calls NETM() to set balances[owner] = totalDistributed = 250000000e18
        c.NETM();

        // Owner burns 125000000e18 tokens
        c.burn(125000000e18);

        // A third party calls getTokens()
        address thirdParty = address(0x1234);
        vm.deal(thirdParty, 1 ether);
        vm.prank(thirdParty);
        c.getTokens{value: 0}();

