pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: the owner calls NETM() to initialize balances[owner] = totalDistributed
        // Then we call transfer with short msg.data to exploit the missing onlyPayloadSize modifier.
        // First, call NETM() via the owner
        c.NETM();

        // Now set up a transfer call with minimal data length (e.g., only 4 bytes) to trigger the bug.
        // Since transfer without onlyPayloadSize will succeed even with short data, it will revert in reference (due to assert on msg.data length) but succeed in buggy.
        // To make the difference observable via public getter: after the transfer, check a balance.
        // We'll make the transfer from owner to address(1) with amount 1, but via raw call to bypass the modifier.
        // However, the test must use the public surface. Instead, we can use the fact that the buggy transfer with short data will not revert and will emit Transfer, but we need a state difference.
        // Simpler: the bug allows transfer to be called with arbitrary data; we can call it with data that encodes (address(1), 1) but with extra zero padding removed? Actually the issue is that the modifier checks msg.data.length >= 68; without it, a call with exactly 68 bytes works fine. To trigger divergence, we need a call with msg.data.length < 68 that would revert in reference but not in buggy.
        // We'll craft a call to transfer with shortened data. In Solidity, we can do a low-level call with abi.encodeWithSignature truncated.
        bytes memory shortData = abi.encodeWithSignature("transfer(address,uint256)", address(1), uint256(1));
        // shortData is 68 bytes. To make it shorter, we can trim the last bytes? But the function selector is fixed. Actually we can call with only the function selector (4 bytes) and no arguments — that triggers the modifier check failure in reference.
        bytes memory selectorOnly = abi.encodeWithSignature("transfer(address,uint256)"); // this gives only 4 bytes? No, abi.encodeWithSignature with no args gives only function selector (4 bytes). Actually abi.encodeWithSignature returns bytes4? Better: manually construct 4 bytes.
        bytes memory callData = hex"a9059cbb"; // transfer selector
        // Perform low-level call from owner
        vm.prank(address(this)); // owner is address(this) because contract deployed with msg.sender = address(this)
        (bool success, ) = address(c).call(callData);
        // For reference, this call reverts (due to assert), success = false. For buggy, it succeeds, success = true.
        // But we need an assertion that fails on buggy. So we assert that the call reverts (success == false).
        assertTrue(!success, "Reference should revert on short data");
    }
}

