pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        address attacker = address(0x1234);

        // Fund attacker with some Ether to trigger payable fallback
        vm.deal(attacker, 1 ether);

        // First, call NETM() as owner
        c.NETM();

        // Now attacker sends a call with exactly 0 bytes of calldata (triggering receive())
        // but abi.encodeWithSignature of a non-existent function also works with 0x prefix
        vm.prank(attacker);
        (bool success, ) = address(c).call{value: 0.001 ether}("");
        assertTrue(success);

        // The reference: balanceOf(owner) should be totalDistributed (250000000e18)
        // The mutant: balanceOf(owner) becomes 0 because the transfer function without payload size check allows the fallback to call distr with attacker's address
        uint256 ownerBalance = c.balanceOf(owner);
        assertTrue(ownerBalance != 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner calls NETM() to set balances[owner] = totalDistributed = 250000000e18
        address owner = address(this);
        vm.prank(owner);
        c.NETM();

        // Now a different address attempts to call transfer with 0-length calldata
        // We use a low-level call to craft calldata shorter than (2*32+4)
        address other = address(0x1);
        vm.deal(other, 1 ether);
        vm.prank(other);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, address(0x2), 0));
        // The reference reverts because onlyPayloadSize requires msg.data.length >= 68 (4+64)
        // The bug does not have the modifier, so it returns true
        // After the call, balances should be unchanged if it reverted
        // We check balance of owner to see if NETM() effect persists: reference has it, bug has it too (no change)
        // Actually both keep the balance, but the call success differs
        bool ok;
        try c.transfer(address(0x2), 0) { ok = true; } catch { ok = false; }
        // The reference contract (with modifier) reverts on direct call with normal calldata length 68 (passes modifier)
        // To differentiate, we rely on the low-level call result:
        // For the reference, the low-level call with exact selector+0+0 has calldata length 68 => passes modifier
        // We need a shorter call: use 0-length calldata
        // Actually we already did that; but the difference is that the reference reverts on the low-level call with 0-length calldata
        // Let's redo: just assert that a direct call with insufficient data reverts in reference but not in bug
        // Simpler: we call transfer with a method signature but too short calldata via low-level
        bytes memory shortCalldata = abi.encodeWithSelector(c.transfer.selector); // just selector, no args => length 4
        (bool okShort, ) = address(c).call(shortCalldata);
        // Reference reverts (assert triggered), bug returns true (no modifier)
        assertTrue(okShort == false, "Bug fails: should revert on short calldata");
    }
}

