        // Prepare a low-level call to transfer with only 64 bytes of data (less than 2*32+4=68 bytes)
        address(c).call(abi.encodeWithSignature("transfer(address,uint256)", address(0xdead), 0));

        // Assert the transfer call reverted (reference does; buggy does not)
        // We use a try/catch to capture revert behavior
        bool ok = false;
        try c.transfer(address(0xdead), 0) {
