contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call NETM() to set owner balance to totalDistributed (250000000e18)
        c.NETM();

        // totalSupply = 500000000e18
        // totalDistributed = 250000000e18 => totalRemaining = 250000000e18
        // value = 2500e18
        // After NETM(), totalDistributed = 250000000e18, totalRemaining = 250000000e18

        address investor = address(0x1234);
        vm.deal(investor, 1 ether);

        // First call: value (2500e18) == totalRemaining (250000000e18)? No, 2500e18 < 250000000e18, so condition fails in both
        // Actually need value == totalRemaining to trigger the difference. Let's adjust: we need value to equal totalRemaining.
        // But value is fixed at 2500e18 and totalRemaining is 250000000e18. They are not equal.
        // To make them equal, we need to reduce totalRemaining. The only way is to call getTokens() repeatedly 
        // to increase totalDistributed. But each call distributes 2500e18 and blacklists caller.
        // We can use many different callers to drain totalRemaining until it equals value (2500e18).
        // Let's compute: totalRemaining starts at 250000000e18. Each call distributes 2500e18.
        // After 99999 calls, totalRemaining = 250000000e18 - 99999*2500e18 = 250000000e18 - 249997500e18 = 2500e18 (since 99999*2500 = 249997500, 250000000 - 249997500 = 2500).
        // Exactly! After 99999 calls from different addresses, totalRemaining = 2500e18 = value.
        // Then the 100000th caller will trigger the boundary.
        for (uint i = 0; i < 99999; i++) {
